(()=>{'use strict';const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,$=id=>document.getElementById('P10-'+id);let p={record:0,delta:0,angle:30,zero:false},result={};const X=[0,2,4,6,8,10],Y=[1,42,80,120,162,201],blue='#246989',red='#b95235',ink='#203643';
const txt=(x,y,s,size=13,anchor='start',color=ink)=>`<text x="${x}" y="${y}" font-size="${size}" text-anchor="${anchor}" fill="${color}">${s}</text>`;
const line=(x1,y1,x2,y2,color='#d7dfdf',width=1)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}"/>`;
const dot=(x,y,color,r=4)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const poly=(points,color,width=2,dash='')=>`<polyline points="${points.map(v=>v.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
function update(){const y=Y.slice();y[p.record]+=p.delta;let a,b;if(p.zero){a=X.reduce((s,v,i)=>s+v*y[i],0)/220;b=0;}else{a=X.reduce((s,v,i)=>s+(v-5)*y[i],0)/70;b=y.reduce((s,v)=>s+v,0)/6-5*a;}const residual=y.map((v,i)=>v-a*X[i]-b),sse=residual.reduce((s,v)=>s+v*v,0),w=200/a,h=80/a,t=p.angle*Math.PI/180,c=Math.cos(t),s=Math.sin(t),before=[[0,0],[w,0],[w,h],[0,h]],after=before.map(([x,y])=>[x*c-y*s,x*s+y*c]);result={...p,slope:a,intercept:b,sse,width_mm:w,height_mm:h,vertex1:after[1],residual,vertices:after,pixel_readings:y};$('record').value=p.record;$('delta').value=p.delta;$('angle').value=p.angle;$('zero').checked=p.zero;$('delta-value').textContent=p.delta+' px';$('angle-value').textContent=p.angle+'°';$('stats').innerHTML=`<p><strong>a = ${a.toFixed(6)} px/mm · b = ${b.toFixed(6)} px</strong><br>${tr('残差平方和','Squared residual sum')} = ${sse.toFixed(6)} px² · ${tr('宽 × 高','Width × height')} = ${w.toFixed(6)} × ${h.toFixed(6)} mm</p>`;
let svg=txt(55,27,tr('标定：已知长度 → 像素读数','Calibration: known length → pixel reading'),15)+txt(520,27,tr('标定后旋转：横纵等比例','Calibrated rotation: equal axis scales'),15);const xp=v=>65+v*35,yp=v=>275-(v+25)*.8;for(let v=0;v<=10;v+=2){svg+=line(xp(v),55,xp(v),275)+txt(xp(v),296,v,12,'middle');}for(let v=0;v<=225;v+=25){svg+=line(65,yp(v),415,yp(v))+txt(55,yp(v)+4,v,12,'end');}svg+=txt(240,320,tr('已知长度 / mm','Known length / mm'),13,'middle')+txt(65,48,tr('读数 / px','Reading / px'),13);svg+=poly([[xp(0),yp(b)],[xp(10),yp(10*a+b)]],blue);y.forEach((v,i)=>{svg+=line(xp(X[i]),yp(v),xp(X[i]),yp(a*X[i]+b),red,1.5)+dot(xp(X[i]),yp(v),i===p.record?red:blue,i===p.record?6:4);});
const ry=v=>510-v*5;svg+=txt(65,365,tr('每条记录的残差','Residual for each record'),15);for(let v=-20;v<=20;v+=10)svg+=line(65,ry(v),415,ry(v),v===0?'#83949a':'#d7dfdf')+txt(55,ry(v)+4,v,12,'end');for(let i=0;i<6;i++){svg+=line(xp(X[i]),ry(0),xp(X[i]),ry(residual[i]),i===p.record?red:blue,3)+dot(xp(X[i]),ry(residual[i]),i===p.record?red:blue)+txt(xp(X[i]),632,X[i],12,'middle');}svg+=txt(65,389,tr('观测 − 拟合 / px','Observed − fitted / px'),13)+txt(240,655,tr('已知长度 / mm','Known length / mm'),13,'middle');
const gx=v=>705+v*12,gy=v=>270-v*12;for(let v=-10;v<=10;v+=5){svg+=line(gx(v),102,gx(v),438,v===0?'#83949a':'#d7dfdf')+txt(gx(v),459,v,12,'middle')+line(537,gy(v),873,gy(v),v===0?'#83949a':'#d7dfdf')+txt(527,gy(v)+4,v,12,'end');}svg+=txt(705,486,'x / mm',13,'middle')+txt(537,82,'y / mm',13);svg+=poly([...before,before[0]].map(([x,y])=>[gx(x),gy(y)]),'#83949a',2,'5 4')+poly([...after,after[0]].map(([x,y])=>[gx(x),gy(y)]),red,2.5);after.forEach(([x,y],i)=>{svg+=dot(gx(x),gy(y),red,4)+txt(gx(x)+6,gy(y)-7,i,12,'start',red);});svg+=txt(535,530,tr('旋转后顶点1 / mm','Rotated vertex 1 / mm'),14)+txt(535,556,`(${after[1][0].toFixed(6)}, ${after[1][1].toFixed(6)})`,15)+txt(535,591,tr('旋转前后边长保持相同','Side lengths are preserved by rotation'),13);$('chart').innerHTML=svg;}
function set(q){p={...p,...q};p.record=Math.max(0,Math.min(5,Math.round(Number(p.record))));p.delta=Math.max(-20,Math.min(20,Number(p.delta)));p.angle=Math.max(0,Math.min(180,Number(p.angle)));p.zero=Boolean(p.zero);update();}function reset(){p={record:0,delta:0,angle:30,zero:false};update();}['record','delta','angle'].forEach(k=>$(k).addEventListener('input',()=>set({[k]:Number($(k).value)})));$('zero').addEventListener('change',()=>set({zero:$('zero').checked}));$('reset').addEventListener('click',reset);window.CourseLab={set,reset,state:()=>JSON.parse(JSON.stringify(result))};reset();})();
